#nullable enable // autogenerated

using System;
using Cysharp.Threading.Tasks;
using MVZ2.Managers;
using Newtonsoft.Json;
using UnityEngine;

namespace MVZ2.ResourcePacks
{
    public class ResourcePackMetadataReader
    {
        public ResourcePackMetadataReader(MainManager main)
        {
            Main = main;
        }
        public async UniTask<ResourcePackMetadata?> ReadMetadata(ResourceLoader loader, string key)
        {
            try
            {
                if (!loader.Exists(METADATA_FILENAME))
                    return null;

                var json = await loader.LoadStringAsync(METADATA_FILENAME);
                if (string.IsNullOrEmpty(json))
                    return null;
                var metadata = JsonConvert.DeserializeObject<ResourcePackMetadata>(json);
                if (metadata != null)
                {
                    var iconBytes = await loader.LoadBytesAsync(ICON_FILENAME);
                    if (iconBytes != null)
                    {
                        var texture = Main.ResourceManager.GenerateTextureFromBytes(iconBytes, metadata.name ?? "pack");
                        var rect = new Rect(0, 0, texture.width, texture.height);
                        var pivot = new Vector2(0.5f, 0.5f);
                        metadata.icon = Main.ResourceManager.CreateSprite(texture, rect, pivot, key, category: ResourcePackManager.RESOURCE_PACK_ICON_SPRITE_CATEGORY);
                    }
                }
                return metadata;
            }
            catch (Exception e)
            {
                Debug.LogError($"读取语言包Zip的元数据失败：{e}");
                return null;
            }
        }
        public MainManager Main { get; private set; }
        public const string METADATA_FILENAME = "pack.json";
        public const string ICON_FILENAME = "pack.png";
    }
}
